<script setup>
import {ref,onMounted,onUnmounted} from 'vue'
import {api} from '../lib/api'
import {useArcade} from '../stores/arcade'
const props=defineProps({embedded:Boolean});
const s=useArcade(),dialog=ref(null),state=ref(null),busy=ref(false),error=ref('')
async function open(){error.value='';busy.value=true;if(!props.embedded)dialog.value.showModal();try{state.value=await api('/gift')}catch(e){error.value=e.message}finally{busy.value=false}}
async function action(kind,box){if(busy.value)return;busy.value=true;error.value='';try{state.value=await api('/gift/'+kind,{method:'POST',body:kind==='pick'?{box}:{day:state.value.day}});if(kind==='claim')await s.refresh()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(()=>{if(props.embedded)open()});onUnmounted(()=>dialog.value?.close?.())
defineExpose({refresh:open})
</script>
<template><button v-if="!embedded&&s.user?.role==='student'" class="profile-link gift-launch" aria-label="하루 한 번 선물 상자" @click="open">🎁 선물</button><component :is="embedded?'section':'dialog'" ref="dialog" :class="['daily-gift',{'embedded-gift':embedded}]" aria-labelledby="gift-title"><button v-if="!embedded" class="text-button gift-close" aria-label="선물 창 닫기" :disabled="busy" @click="dialog.close()">✕</button><p class="eyebrow">DAILY GIFT</p><h2 id="gift-title">하루 한 번, 나의 선물!</h2><p>세 상자 중 하나를 골라 주세요.<br/>0P · 500P · 1000P가 각각 1/3 확률로 나와요.</p><div class="gift-boxes"><button v-for="i in 3" :key="i" :disabled="busy||!state||!!state.gift" :class="{chosen:state?.gift?.box===i-1}" :aria-label="'선물 상자 '+i" @click="action('pick',i-1)"><span>{{state?.gift?.box===i-1?'✨':'🎁'}}</span><b>{{i}}번 상자</b></button></div><div v-if="state?.gift" role="status"><h3>{{state.gift.amount.toLocaleString()}} P!</h3><p v-if="state.gift.claimed_at">오늘 선물을 수령했어요. 내일 다시 만나요!</p><button v-else :disabled="busy" @click="action('claim')">{{busy?'수령 중…':state.gift.amount+' P 수령하기'}}</button></div><p v-if="error" role="alert">{{error}}</p></component></template>
<style scoped>.daily-gift{box-sizing:border-box;width:min(560px,calc(100vw - 24px));max-height:90dvh;overflow:auto;padding:26px;border:3px solid var(--rpg-edge);border-radius:18px;background:var(--rpg-paper);color:var(--rpg-ink);box-shadow:0 7px var(--rpg-shadow);text-align:center}.daily-gift::backdrop{background:#182436b3;backdrop-filter:blur(3px)}.daily-gift h2{font-size:22px}.daily-gift p{font-size:13px;line-height:1.8}.daily-gift small{font-size:11px}.gift-close{position:absolute;top:12px;right:12px;margin:0;padding:6px;min-width:30px;min-height:30px}.gift-boxes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:24px 0}.gift-boxes button{display:flex;flex-direction:column;align-items:center;gap:12px;padding:18px 8px;min-width:0}.gift-boxes span{font-size:50px;filter:drop-shadow(0 4px 0 #0003)}.gift-boxes b{font-size:12px}.gift-boxes .chosen{outline:3px solid var(--rpg-mid);outline-offset:2px}.gift-boxes button.chosen:disabled{opacity:1}.gift-launch{white-space:nowrap}@media(max-width:600px){.daily-gift{padding:20px 12px}.gift-boxes{gap:6px}.gift-boxes span{font-size:36px}.daily-gift h2{font-size:18px}}</style>
